patch:
diff --git a/repro/no-unused-expressions-use-strict.js b/repro/no-unused-expressions-use-strict.js
new file mode 100644
index 0000000..12f642e
--- /dev/null
+++ b/repro/no-unused-expressions-use-strict.js
@@ -0,0 +1,44 @@
+"use strict";
+
+/*
+ * Reproduction: `no-unused-expressions` reports the `'use strict'` directive
+ * when the code is parsed with `languageOptions.ecmaVersion: 3`
+ * (core-js lints packages/core-js with ecmaVersion 3 and these rule options).
+ *
+ * Exits non-zero while the bug is present, zero once `'use strict'` is no
+ * longer reported. Run from the repo root:
+ *   node repro/no-unused-expressions-use-strict.js
+ */
+
+const { Linter } = require("../lib/api");
+
+const linter = new Linter();
+const code = "'use strict';\nfoo();\n\nfunction f() {\n  'use strict';\n  return 1;\n}\n";
+const ruleOptions = { allowShortCircuit: true, allowTernary: true, allowTaggedTemplates: true };
+
+function lint(ecmaVersion) {
+	return linter.verify(code, [
+		{
+			languageOptions: { ecmaVersion, sourceType: "script" },
+			rules: { "no-unused-expressions": ["error", ruleOptions] },
+		},
+	], "file.js");
+}
+
+// Control: same code with ecmaVersion 5 (and "latest"); expected to be clean.
+for (const v of [5, "latest"]) {
+	const msgs = lint(v);
+	console.log(`ecmaVersion ${v}: ${msgs.length} problem(s)`);
+	for (const m of msgs) {
+		console.log(`  ${m.line}:${m.column} ${m.ruleId}: ${m.message}`);
+	}
+}
+
+// The reported case.
+const messages = lint(3);
+console.log(`ecmaVersion 3: ${messages.length} problem(s)`);
+for (const m of messages) {
+	console.log(`  ${m.line}:${m.column} ${m.ruleId}: ${m.message}`);
+}
+
+process.exitCode = messages.length ? 1 : 0;
